// Submits the Claude review for one pull request, as the vynr-reviewer GitHub App.
// No model runs here: this script only applies fixed gates to the model's JSON
// verdict. It never merges and never enables auto-merge. Policy: CLAUDE.md.
//
// Env: GH_TOKEN (App installation token), GITHUB_REPOSITORY, PR, HEAD_SHA, VERDICT_JSON.

const GH_TOKEN = process.env.GH_TOKEN;
const repo = process.env.GITHUB_REPOSITORY;
const PR = process.env.PR;
const HEAD_SHA = process.env.HEAD_SHA;
const VERDICT_JSON = process.env.VERDICT_JSON;
const API = 'https://api.github.com';

// Changes here need a human code owner. The bot may comment but never approves them.
const PROTECTED = [
  /^\.github\//,
  /^\.claude\//,
  /^CLAUDE\.md$/,
  /^AGENTS\.md$/,
  /^\.mcp\.json$/,
  /^CODEOWNERS$/,
  /^\.github\/CODEOWNERS$/,
  /^docs\/PR_REVIEW_SETUP\.md$/,
  /(^|\/)\.env/,
  /^server\/src\/(config|pricing|store)\.ts$/,
];
const FOOTER = '\n\n---\n_Generated by [Claude Code](https://claude.ai/code)_';

async function gh(path, init = {}) {
  const res = await fetch(`${API}${path}`, {
    ...init,
    headers: {
      authorization: `Bearer ${GH_TOKEN}`,
      accept: 'application/vnd.github+json',
      'x-github-api-version': '2022-11-28',
      ...(init.body ? { 'content-type': 'application/json' } : {}),
    },
  });
  if (!res.ok) throw new Error(`${init.method ?? 'GET'} ${path} -> ${res.status} ${await res.text()}`);
  return res.status === 204 ? null : res.json();
}

async function paged(path) {
  const all = [];
  for (let page = 1; page <= 30; page++) {
    const sep = path.includes('?') ? '&' : '?';
    const items = await gh(`${path}${sep}per_page=100&page=${page}`);
    const list = Array.isArray(items) ? items : items.check_runs;
    all.push(...list);
    if (list.length < 100) break;
  }
  return all;
}

/** Right-side line numbers present in a unified diff patch (comments can only go there). */
function commentableLines(patch = '') {
  const lines = new Set();
  let n = 0;
  for (const l of patch.split('\n')) {
    const h = /^@@ -\d+(?:,\d+)? \+(\d+)/.exec(l);
    if (h) {
      n = Number(h[1]);
      continue;
    }
    if (l.startsWith('-')) continue;
    if (l.startsWith('+') || l.startsWith(' ')) lines.add(n++);
  }
  return lines;
}

function fail(msg) {
  console.error(msg);
  process.exit(1);
}

if (!GH_TOKEN || !repo || !/^\d+$/.test(PR ?? '') || !/^[0-9a-f]{40}$/.test(HEAD_SHA ?? '')) fail('Missing or invalid inputs.');

let verdict;
try {
  verdict = JSON.parse(VERDICT_JSON ?? '');
} catch {
  fail('The review job returned no valid verdict; nothing submitted.');
}
if (!['approve', 'request_changes'].includes(verdict?.verdict) || !Array.isArray(verdict.findings)) fail('Malformed verdict.');

const pr = await gh(`/repos/${repo}/pulls/${PR}`);
if (pr.state !== 'open') fail('PR is not open.');
if (pr.head.sha !== HEAD_SHA) fail(`PR head moved from ${HEAD_SHA} to ${pr.head.sha}; the new commit gets its own review.`);
if (pr.head.repo?.full_name !== repo) fail('Fork PRs are not reviewed automatically.');

// Every check on the reviewed commit must have finished green.
const checks = await paged(`/repos/${repo}/commits/${HEAD_SHA}/check-runs`);
const verify = checks.find((c) => c.name === 'verify');
const bad = checks.filter((c) => c.status !== 'completed' || !['success', 'skipped', 'neutral'].includes(c.conclusion));
const ciGreen = verify?.conclusion === 'success' && bad.length === 0;

const files = await paged(`/repos/${repo}/pulls/${PR}/files`);
const protectedHits = files.map((f) => f.filename).filter((p) => PROTECTED.some((re) => re.test(p)));

const byPath = new Map(files.map((f) => [f.filename, commentableLines(f.patch)]));
const inline = [];
const elsewhere = [];
for (const f of verdict.findings.slice(0, 30)) {
  const text = `**${f.severity}**: ${String(f.message).slice(0, 1500)}`;
  if (byPath.get(f.path)?.has(f.line)) inline.push({ path: f.path, line: f.line, side: 'RIGHT', body: text + FOOTER });
  else elsewhere.push(`- \`${f.path}:${f.line}\` ${text}`);
}
const serious = verdict.findings.some((f) => f.severity === 'blocking' || f.severity === 'major');

let event;
const notes = [];
if (verdict.verdict === 'request_changes' || serious) {
  event = 'REQUEST_CHANGES';
} else if (protectedHits.length) {
  event = 'COMMENT';
  notes.push(`Not approved automatically: this PR changes protected paths that need a human code owner (${protectedHits.join(', ')}).`);
} else if (!ciGreen) {
  event = 'COMMENT';
  notes.push('Not approved automatically: not every check on this commit has passed.');
} else {
  event = 'APPROVE';
  notes.push('Approved by the automated reviewer for this exact commit. A new push dismisses this approval. Merging stays with a person.');
}

const body = [
  `Automated review of ${HEAD_SHA.slice(0, 12)}.`,
  '',
  String(verdict.summary ?? '').slice(0, 2000),
  ...(elsewhere.length ? ['', 'Findings outside the changed lines:', ...elsewhere] : []),
  '',
  ...notes,
].join('\n');

// Last check immediately before submitting, then bind the review to the reviewed commit.
const again = await gh(`/repos/${repo}/pulls/${PR}`);
if (again.head.sha !== HEAD_SHA) fail('PR head moved during review; nothing submitted.');

await gh(`/repos/${repo}/pulls/${PR}/reviews`, {
  method: 'POST',
  body: JSON.stringify({ commit_id: HEAD_SHA, event, body: body + FOOTER, comments: inline }),
});
console.log(`Submitted ${event} on #${PR} @ ${HEAD_SHA} with ${inline.length} inline comment(s).`);
